from typing import NamedTuple


class Assignment(NamedTuple):
    weight: float
    kind: str


class Gradebook:
    def __init__(self) -> None:
        self.assignments: dict[str, Assignment] = {}
        self.grades: defaultdict[str, dict[str, float]] = defaultdict(dict)

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = Assignment(weight=float(weight), kind=kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the allowed scale 2.0 to 5.0.")
        self.grades[student][assignment] = float(grade)

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        quizzes: list[tuple[float, float]] = []
        homeworks: list[tuple[float, float]] = []

        for name, assignment in self.assignments.items():
            grade = student_grades.get(name, 2.0)
            item = (grade, assignment.weight)
            if assignment.kind == "quiz":
                quizzes.append(item)
            else:
                homeworks.append(item)

        # Drop the lowest quiz grade if there is more than one quiz
        if len(quizzes) > 1:
            quizzes.remove(min(quizzes, key=lambda item: item[0]))

        active_items = homeworks + quizzes
        total_weight = sum(weight for _, weight in active_items)

        if total_weight == 0.0:
            return 0.0

        total_weighted_sum = sum(grade * weight for grade, weight in active_items)
        return round(total_weighted_sum / total_weight, 2)
